#include "durable_storage.h"
#include <sqlite3.h>
#include <cassert>
#include <cstdio>
#include <iostream>
#include <thread>
#include <atomic>
using namespace beefiscal::idf;
static std::string scalar(const char*path,const char*query){sqlite3*d{};sqlite3_stmt*q{};assert(sqlite3_open(path,&d)==SQLITE_OK);assert(sqlite3_prepare_v2(d,query,-1,&q,nullptr)==SQLITE_OK);assert(sqlite3_step(q)==SQLITE_ROW);const auto*p=sqlite3_column_text(q,0);std::string out=p?(const char*)p:"";sqlite3_finalize(q);sqlite3_close(d);return out;}
int main(int argc,char**argv){assert(argc==3);const std::string mode=argv[1];const char*path=argv[2];remove(path);DurableStorage s;assert(s.open_database_for_test(path)==ESP_OK);AuthorityReservation a;
 if(mode=="format"){assert(s.configure_authority("DT636497",1,9999999,1)==ESP_OK);assert(s.reserve_authority(a,"0001")==ESP_OK);assert(a.unp=="DT636497-0001-0000001");assert(s.configure_authority("DT636497",1,9999999,1)==ESP_OK);assert(s.reserve_authority(a,"0001")==ESP_OK&&a.unp=="DT636497-0001-0000002");s.close();assert(s.open_database_for_test(path)==ESP_OK);assert(s.reserve_authority(a,"0001")==ESP_OK&&a.unp=="DT636497-0001-0000003");}
 else if(mode=="configuration"){for(const char*p:{"TEST-","DT636497-1-","DT63649x-0001-","dt636497-0001-","DT636497-0!01-"})assert(s.configure_authority(p,1,100,1)==ESP_ERR_INVALID_ARG);assert(s.configure_authority("DT636497",1,10000000,1)==ESP_ERR_INVALID_ARG);assert(s.configure_authority("DT636497",1,10,1)==ESP_OK);assert(s.reserve_authority(a,"0001")==ESP_OK);assert(s.configure_authority("DT636498",1,10,1)==ESP_ERR_INVALID_VERSION);assert(s.configure_authority("DT636497",2,10,1)==ESP_ERR_INVALID_VERSION);assert(s.configure_authority("DT636497",1,10,2)==ESP_OK);assert(s.reserve_authority(a,"0001")==ESP_OK&&a.unp=="DT636497-0001-0000002");assert(s.configure_authority("DT636497",5,20,3)==ESP_ERR_INVALID_VERSION);assert(s.configure_authority("DT636497",11,20,3)==ESP_OK);assert(s.reserve_authority(a,"0001")==ESP_OK&&a.unp=="DT636497-0001-0000011"&&a.operation_sequence==3);assert(s.configure_authority("DT636498",1,10,4)==ESP_OK);assert(s.configure_authority("DT636497",1,10,5)==ESP_ERR_INVALID_VERSION);}
 else if(mode=="boundary"){assert(s.configure_authority("DT636497",9999999,9999999,1)==ESP_OK);assert(s.reserve_authority(a,"0001")==ESP_OK&&a.unp=="DT636497-0001-9999999");assert(s.reserve_authority(a,"0001")!=ESP_OK);}
 else if(mode=="atomic"){assert(s.configure_authority("DT636497",1,100,1)==ESP_OK);auto callback=[](const AuthorityReservation&a){return "{\"unp\":\""+a.unp+"\"}";};auto v=s.reserve_command("op",std::string(64,'a').c_str(),"HTTP","{}","received","receipt","{\"unp\":\"untrusted\"}",{},1,callback,nullptr,"0001");assert(v.status==ReservationStatus::New);assert(v.authority.unp=="DT636497-0001-0000001");assert(scalar(path,"SELECT execution_unp FROM receipt_authority")==v.authority.unp);assert(scalar(path,"SELECT json_extract(payload,'$.unp') FROM event_outbox")==v.authority.unp);assert(s.reserve_command("op",std::string(64,'a').c_str(),"HTTP","{}","received","receipt","{}",{},1,callback,nullptr,"0001").status==ReservationStatus::Duplicate);assert(scalar(path,"SELECT next_unp FROM authority_state")=="2");int seen=0;assert(s.recovery(10,[&](const RecoveryItem&i){assert(i.canonical_unp==v.authority.unp);++seen;return true;})==ESP_OK&&seen==1);}
 else if(mode=="policy"){assert(s.configure_authority("DT636497",1,1,1)==ESP_OK);auto event=[](const AuthorityReservation&){return "{}";};auto reserve=[&](const char*id,const char*unp,const char*op){return s.reserve_command(id,std::string(64,'a').c_str(),"MQTT","{}",id,id,"{}",{},1,event,unp,op);};auto report=reserve("report",nullptr,nullptr);assert(report.status==ReservationStatus::New&&report.authority.unp.empty()&&report.authority.unp_sequence==0&&report.authority.operation_sequence==1);auto sale=reserve("sale",nullptr,"A001");assert(sale.status==ReservationStatus::New&&sale.authority.unp=="DT636497-A001-0000001"&&sale.authority.unp_sequence==1);assert(reserve("exhausted",nullptr,"B002").status!=ReservationStatus::New);auto reversal=reserve("reversal","DT636497-B002-0000042",nullptr);assert(reversal.status==ReservationStatus::New&&reversal.authority.unp=="DT636497-B002-0000042"&&reversal.authority.unp_sequence==0&&reversal.authority.operation_sequence==3);assert(reserve("cashout",nullptr,nullptr).status==ReservationStatus::New);assert(scalar(path,"SELECT next_unp FROM authority_state")=="2");assert(scalar(path,"SELECT count(*) FROM receipt_authority WHERE unp_sequence=0")=="3");assert(scalar(path,"SELECT execution_unp FROM receipt_authority WHERE receipt_id='reversal'")=="DT636497-B002-0000042");}
 else if(mode=="operators"){assert(s.configure_authority("DT636497",1,100,1)==ESP_OK);for(const char*op:{"","1","00000","00-1","00!1"})assert(s.reserve_authority(a,op)!=ESP_OK);assert(s.reserve_authority(a)!=ESP_OK);assert(s.reserve_authority(a,"A001")==ESP_OK&&a.unp=="DT636497-A001-0000001");assert(s.reserve_authority(a,"B002")==ESP_OK&&a.unp=="DT636497-B002-0000002");s.close();assert(s.open_database_for_test(path)==ESP_OK);assert(s.reserve_authority(a,"A001")==ESP_OK&&a.unp=="DT636497-A001-0000003");}
 else if(mode=="assigned"){assert(s.configure_authority("DT636497",1,100,1)==ESP_OK);auto callback=[](const AuthorityReservation&){return "{}";};auto reserve=[&](const char*id,const char*unp){return s.reserve_command(id,std::string(64,'a').c_str(),"MQTT","{}",id,id,"{}",{},1,callback,unp,nullptr,true);};auto a=reserve("online","DT636497-A001-0000500");assert(a.status==ReservationStatus::New&&a.authority.unp_sequence==0&&a.authority.unp=="DT636497-A001-0000500");assert(scalar(path,"SELECT next_unp FROM authority_state")=="1");assert(reserve("online","DT636497-A001-0000500").status==ReservationStatus::Duplicate);assert(reserve("different-operation","DT636497-A001-0000500").status!=ReservationStatus::New);assert(reserve("different-operator","DT636497-B002-0000500").status!=ReservationStatus::New);assert(reserve("leased-overlap","DT636497-A001-0000050").status!=ReservationStatus::New);assert(scalar(path,"SELECT count(*) FROM operations")=="1");assert(s.configure_authority("DT636497",101,200,2)==ESP_OK);assert(reserve("retired-lease-overlap","DT636497-A001-0000050").status!=ReservationStatus::New);assert(s.configure_authority("DT636497",400,600,3)!=ESP_OK);s.close();assert(s.open_database_for_test(path)==ESP_OK);assert(reserve("restarted-duplicate","DT636497-A001-0000500").status!=ReservationStatus::New);int seen=0;assert(s.recovery(10,[&](const RecoveryItem&i){assert(i.canonical_unp=="DT636497-A001-0000500");++seen;return true;})==ESP_OK&&seen==1);sqlite3*d{};assert(sqlite3_open(path,&d)==SQLITE_OK);assert(sqlite3_exec(d,"CREATE TRIGGER fault BEFORE INSERT ON sale_unp_claims BEGIN SELECT RAISE(ABORT,'claim failed'); END;",nullptr,nullptr,nullptr)==SQLITE_OK);sqlite3_close(d);assert(reserve("fault","DT636497-A001-0000501").status!=ReservationStatus::New);assert(scalar(path,"SELECT count(*) FROM operations")=="1");assert(scalar(path,"SELECT count(*) FROM receipts")=="1");assert(scalar(path,"SELECT count(*) FROM event_outbox")=="1");assert(scalar(path,"SELECT next_operation FROM authority_state")=="2");}
 else if(mode=="concurrent-assigned"){assert(s.configure_authority("DT636497",1,100,1)==ESP_OK);DurableStorage other;assert(other.open_database_for_test(path)==ESP_OK);std::atomic<int>ready{0};ReservationStatus outcomes[2];auto task=[&](DurableStorage&db,int n){ready.fetch_add(1);while(ready.load()!=2)std::this_thread::yield();std::string id="op-"+std::to_string(n);outcomes[n]=db.reserve_command(id.c_str(),std::string(64,'a').c_str(),"MQTT","{}",id.c_str(),id.c_str(),"{}",{},1,[](const AuthorityReservation&){return "{}";},"DT636497-A001-0000500",nullptr,true).status;};std::thread one(task,std::ref(s),0),two(task,std::ref(other),1);one.join();two.join();assert((outcomes[0]==ReservationStatus::New)!=(outcomes[1]==ReservationStatus::New));assert(scalar(path,"SELECT count(*) FROM operations")=="1");assert(scalar(path,"SELECT count(*) FROM sale_unp_claims")=="1");assert(scalar(path,"SELECT next_unp FROM authority_state")=="1");assert(scalar(path,"SELECT next_operation FROM authority_state")=="2");}
 else assert(false);std::cout<<mode<<" actual SQLite authority PASS\n";}
